CREATE TABLE public.customers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', channel TEXT NOT NULL DEFAULT 'whatsapp', notes TEXT NOT NULL DEFAULT '', purchases TEXT NOT NULL DEFAULT '', last_message TEXT NOT NULL DEFAULT '', last_seen TIMESTAMPTZ DEFAULT now(), created_at TIMESTAMPTZ NOT NULL DEFAULT now()); GRANT SELECT, INSERT, UPDATE, DELETE ON public.customers TO anon; GRANT ALL ON public.customers TO service_role; ALTER TABLE public.customers ENABLE ROW LEVEL SECURITY; CREATE POLICY "public customers" ON public.customers FOR ALL TO anon USING (true) WITH CHECK (true); CREATE TABLE public.channels (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), platform TEXT NOT NULL, label TEXT NOT NULL DEFAULT '', auto_reply BOOLEAN NOT NULL DEFAULT true, connected BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now()); GRANT SELECT, INSERT, UPDATE, DELETE ON public.channels TO anon; GRANT ALL ON public.channels TO service_role; ALTER TABLE public.channels ENABLE ROW LEVEL SECURITY; CREATE POLICY "public channels" ON public.channels FOR ALL TO anon USING (true) WITH CHECK (true); CREATE TABLE public.channel_messages (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), channel TEXT NOT NULL DEFAULT 'whatsapp', customer_name TEXT NOT NULL DEFAULT '', customer_phone TEXT NOT NULL DEFAULT '', direction TEXT NOT NULL DEFAULT 'in', text TEXT NOT NULL DEFAULT '', replied BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now()); GRANT SELECT, INSERT, UPDATE, DELETE ON public.channel_messages TO anon; GRANT ALL ON public.channel_messages TO service_role; ALTER TABLE public.channel_messages ENABLE ROW LEVEL SECURITY; CREATE POLICY "public channel_messages" ON public.channel_messages FOR ALL TO anon USING (true) WITH CHECK (true);